function nb(v){return String(v).replace(/(^|[ \n])(в|к|с|у|о|и|а|на|по|от|до|за) /gi,'$1$2\u00a0');}
function shape(s,g,x,y,w,h,fill=C.pale,stroke='none',sw=0){return s.shapes.add({geometry:g,position:{left:x,top:y,width:w,height:h},fill,line:{fill:stroke,width:sw}});}
function t(s,txt,x,y,w,h,size=32,bold=false,color=C.ink,align='left',valign='top'){
 const q=shape(s,'textbox',x,y,w,h,'none');q.text=nb(txt);q.text.style={typeface:FONT,fontSize:size,bold,color,alignment:align,verticalAlignment:valign,autoFit:'none',wrap:'square',insets:{left:0,right:0,top:0,bottom:0}};records.at(-1).text.push(String(txt));return q;
}
function line(s,x1,y1,x2,y2,color=C.line,sw=2){return s.shapes.add({geometry:'line',position:{left:Math.min(x1,x2),top:Math.min(y1,y2),width:Math.max(Math.abs(x2-x1),.1),height:Math.max(Math.abs(y2-y1),.1),verticalFlip:(x2-x1)*(y2-y1)<0},fill:'none',line:{fill:color,width:sw}});}
function box(s,txt,x,y,w,h,fill=C.pale,size=30){const q=shape(s,'roundRect',x,y,w,h,fill);q.borderRadius=16;q.text=nb(txt);q.text.style={typeface:FONT,fontSize:size,color:C.ink,bold:true,alignment:'center',verticalAlignment:'middle',insets:{left:16,right:16,top:10,bottom:10},autoFit:'none'};records.at(-1).text.push(txt);return q;}
function arrow(s,a,b,from='right',to='left',color=C.green,kind='straight'){return s.shapes.connect(a,b,{kind,fromSide:from,toSide:to,line:{fill:color,width:3},tail:{type:'triangle',width:'med',length:'med'}});}
function path(s,pts,color=C.green,sw=3){const xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x||1,h=Math.max(...ys)-y||1;return s.shapes.add({geometry:'custom',position:{left:x,top:y,width:w,height:h},fill:'none',line:{fill:color,width:sw},customPaths:[{width:w,height:h,commands:pts.map((p,i)=>({[i?'lineTo':'moveTo']:{x:p[0]-x,y:p[1]-y}}))}]});}
function wave(s,x,y,w,h,cycles=6,color=C.green){return path(s,Array.from({length:121},(_,i)=>{let u=i/120;return[x+w*u,y+h*Math.sin(2*Math.PI*cycles*u)*Math.exp(-3*u)];}),color,3);}
function slide(title){const s=P.slides.add();s.background.fill=C.white;records.push({n:P.slides.items.length,title,text:[]});t(s,title,64,42,1152,99,46,true);t(s,String(records.length).padStart(2,'0'),1150,677,66,30,24,false,C.green,'right');return s;}
function foot(s,txt){t(s,txt,64,677,1060,30,24,false,C.green);}
function note(s,txt,ids=[]){s.speakerNotes.textFrame.setText(txt+'\n\n'+ids.map(i=>'['+i+'] '+refs[i].join('\n')).join('\n\n'));records.at(-1).notes=txt;records.at(-1).refs=ids;if(ids.length&&!records.at(-1).title.startsWith('Источники'))foot(s,'Источники: '+ids.map(i=>'['+i+']').join(', '));}
function body(s,head,txt,x,y,w=540){t(s,head,x,y,w,48,34,true);t(s,txt,x,y+62,w,150,31);}
function conclusion(s,txt,y=609,size=29){line(s,64,y-16,1216,y-16);t(s,txt,64,y,1152,64,size);}
function step(s,num,head,txt,x,y,w=355){t(s,String(num).padStart(2,'0'),x,y,65,52,36,true,C.green);t(s,head,x+78,y,w-78,89,32,true);t(s,txt,x,y+108,w,190,30);}
function table(s,values,x,y,widths,heights,size=28){const z=s.tables.add({rows:values.length,columns:widths.length,left:x,top:y,width:widths.reduce((a,b)=>a+b),height:heights.reduce((a,b)=>a+b),columnWidths:widths,values:values.map(r=>r.map(nb))});tables.push(P.slides.items.length);records.at(-1).text.push(...values.flat());z.borders.assign({fill:C.line,width:1});for(let r=0;r<values.length;r++){z.rows[r].height=heights[r];for(let c=0;c<widths.length;c++){let q=z.getCell(r,c);q.fill=r===0?C.ink:(c===0?C.pale:C.white);q.text.style={typeface:FONT,fontSize:size,bold:r===0||c===0,color:r===0?C.white:C.ink,autoFit:'none',insets:{left:15,right:12,top:8,bottom:8},verticalAlignment:'middle'};}}return z;}
async function picture(s,file,x,y,w,h,alt,crop){return s.images.add({blob:new Uint8Array(await fs.readFile(file)),contentType:'image/png',alt,fit:'contain',position:{left:x,top:y,width:w,height:h},...(crop?{crop}:{} )});}
function flow(s,labels,y=225,colors=[]){let previous;const gap=45,w=(1152-gap*(labels.length-1))/labels.length;return labels.map((txt,i)=>{const q=box(s,txt,64+i*(w+gap),y,w,104,colors[i]||C.pale,31);if(previous)arrow(s,previous,q);previous=q;return q;});}
function tag(s,label,x,y,w=230){t(s,label,x,y,w,38,26,true,C.green);}

const mathAssets=JSON.parse(await fs.readFile(ROOT+'/assets/formulas/index.json','utf8'));
async function eq(s,id,x,y,w,h,size=34){
 const m=mathAssets[id],scale=Math.min(size/1000,w/m.width,h/m.height);
 records.at(-1).text.push(m.tex);
 return s.images.add({blob:new Uint8Array(await fs.readFile(ROOT+'/assets/formulas/'+id+'.png')),contentType:'image/png',alt:m.tex,fit:'contain',position:{left:x,top:y+(h-m.height*scale)/2,width:m.width*scale,height:m.height*scale}});
}

